  if (!palette) throw new Error(`${def.slug}: unknown palette "${def.palette}"`);
  if (!def.slides || def.slides.length !== 5) throw new Error(`${def.slug}: needs exactly 5 slides`);
  const slides = def.slides.map((sd, i) => {
    const role = ROLES[i];
    if (sd.role !== role.id) throw new Error(`${def.slug}: slide ${i + 1} must be "${role.id}", got "${sd.role}"`);
    const scene = new Scene(role.mode, palette);
    sd.build(scene, { AREA, STAGE, P: scene.P });
    return { role: role.id, roleName: role.name, mode: role.mode, time: sd.time, notes: sd.notes, scene };
