  // anything else is taken as a hex string.
  c(v) {
    if (v == null) return null;
    return this.P[v] || String(v).replace("#", "").toUpperCase();
  }

  rect(x, y, w, h, o = {}) {
    this.items.push({ t: "rect", x, y, w, h, fill: this.c(o.fill), line: this.c(o.line), lineW: o.lineW || 1, opacity: o.opacity ?? 1, dash: o.dash });
    return this;
  }

  ellipse(x, y, w, h, o = {}) {
    this.items.push({ t: "ellipse", x, y, w, h, fill: this.c(o.fill), line: this.c(o.line), lineW: o.lineW || 1, opacity: o.opacity ?? 1 });
    return this;
