        x: bx, y: by, w: bw, h: bh, points: pts,
        fill: it.fill ? fill(it.fill, it.opacity) : { type: "none" },
        line: it.fill && !it.w ? { type: "none" } : { color: it.color, width: it.w, dashType: it.dash ? "dash" : "solid" },
      });
      break;
    }

    case "text": {
      const runs = [];
      it.runs.forEach(r => {
        const parts = r.t.split("\n");
        parts.forEach((p, pi) => {
